; skyward.asm - generated by gen_skyward.py, do not edit
;
; platform game on the SD card (a library program in the RAM)
;
;     python3 gen_skyward.py                  writes skyward.asm next to this script,
;                                             ../../sdcard/SKYWARD.PLC and the course
;                                             files ../../sdcard/SKYWARD/C0.LVL - C5.LVL
;     python3 gen_skyward.py --preview DIR    also draws every course (whole length)
;                                             and a first screen with the Python model
;     python3 test_skyward_sim.py             runs it in placard_sim from a card
;
; A port of World 1 of Skyward Tobi 4 (an NES game by Mark Szlemko,
; github.com/Zebshine/skyward-tobi-4) to the Placard: the story, the cast, the
; courses' ideas and the enemy art are theirs, redrawn for 160 x 112 pixels in
; 16 colors.  The engine is the Placard's own (gen_scroller.py's: no scroll
; registers and no sprite hardware, so the whole playfield is drawn again
; every frame, ahead of the beam).
;
; SCREEN
;     rows   0-31   1 bpp, 1x   four lines of 80 column text: the course's
;                               name, the score line, two lines of story
;     rows  32-479  4 bpp, 4x   the playfield: 160 x 112 pixels of 4 x 4,
;                               16 colors:
;         cells   0-15   the high sky            scrolls at 1/8 speed
;         cells  16-31   clouds                  1/2
;         cells  32-111  the course: 5 rows of   full speed
;                        16 x 16 tiles
;
; FILES ON THE CARD
;     SKYWARD.PLC         the program: the sprite blitter and Tobi's frames at
;                         x0100, the code from x2000
;     SKYWARD/Cn.LVL      one file a course (n = 0-5), read when the course
;                         starts: 6 sectors of tables to x4000-x4BFF (strip
;                         addresses, the tile map, the objects, the sprite
;                         routines' addresses, three lines of text), then a
;                         straight image of the RAM from x6000: the strips
;                         (unrolled code that draws one byte column of a
;                         band or of a tile) and the course's own sprites, in
;                         the video RAM the screen leaves free (offsets
;                         x040-x17F of each 512-byte byte column).
;     Course 0 is the title and the story, 1-4 are played, 5 is the ending.
;
; THE GAME
;     Run right, jump the gaps, land on the Bumblers and Buzzbees (touching
;     one from the side costs a life), collect Mabel's Stunt Medals and reach
;     the windsock.  From course 3 on Tobi has the glider: hold the jump key
;     in the air to glide.  Course 4 is Crow Keep: land on Baron Rook three
;     times.
;     Controls: arrow keys or SNES pad 1 Left / Right, Up / Space / pad B
;     or A to jump (hold to glide), Esc back to the DOS.
;
; Date: 11/13/2026

#include "placard.asm"
#include "placard_lib.asm"

; ---------------------------------------------------------------------------
; program variables (zero page x20-x8F)
; ---------------------------------------------------------------------------
colpage    = 0x20       ; video page of the column being drawn (x61 + 2 * col)
rl         = 0x21       ; strip return address
rh         = 0x22
bw         = 0x23       ; band picture column
gt         = 0x24       ; course tile column 0-127
gj         = 0x25       ;   byte in the tile 0-7
tmp        = 0x26
tmp2       = 0x27
scl        = 0x28       ; scroll: world byte column at the left edge, 0-1023
sch        = 0x29
pxl        = 0x2A       ; player x (left byte column), 0-1023
pxh        = 0x2B
pyl        = 0x2C       ; player y: top cell (pyh) and 1/256 cell
pyh        = 0x2D
vyl        = 0x2E       ; vertical speed, cells / 256 a frame, signed
vyh        = 0x2F
onground   = 0x30
facing     = 0x31       ; 0 right, 6 left (frame offset)
anim       = 0x32
inp        = 0x33       ; input: 1 right, 2 left, 4 jump
course     = 0x34       ; 0 title, 1-4, 5 ending
kind       = 0x35       ; 0 a course to play, 1 a picture (jump: the next course)
glider     = 0x36       ; 1: Tobi has the glider
last_frame = 0x37
lives      = 0x38
score_lo   = 0x39
score_hi   = 0x3A
coins      = 0x3B
hud_dirty  = 0x3C
ta_lo      = 0x3D       ; tile_at: world byte column, cell
ta_hi      = 0x3E
ta_g       = 0x3F
chk_lo     = 0x40       ; where the player last stood
chk_hi     = 0x41
sl_n       = 0x42       ; sprites in the list
s_i        = 0x43
sc         = 0x44       ; this sprite: byte column + 8, top cell + 32
sy         = 0x45
srl        = 0x46       ; return address for the sprite routines
srh        = 0x47
vpg        = 0x48       ; x48-x4F: video page of each of the sprite's 8 columns
SL_LO      = 0x50       ; x50-x5B: sprite routine address, low
SL_HI      = 0x5C       ; x5C-x67: high
SL_C       = 0x68       ; x68-x73: byte column + 8 (0-87)
SL_G       = 0x74       ; x74-x7F: top cell + 32
mode       = 0x80       ; 0 playing, 1 waiting for the jump key, 2 course clear (counting down)
clear_t    = 0x81       ;   frames left of mode 2
o_i        = 0x82       ; object loop index
dlo        = 0x83
dhi        = 0x84
inv        = 0x85       ; frames of safety after a lost life
gliding    = 0x86       ; 1: the glider is open this frame
moved      = 0x87
tmp3       = 0x88
n_med      = 0x89       ; medals in this course
n_en       = 0x8A       ; objects in this course
ll_lo      = 0x8B       ; lose_life's return address
ll_hi      = 0x8C
goal_lo    = 0x8D       ; the course is clear at this byte column
goal_hi    = 0x8E
jprev      = 0x8F       ; the jump key last frame (4 = down)
ekind      = 0x1E       ; (T6) this object's kind
jnow       = 0x1F       ; (T7) the jump key this frame

draw_sprites = 0x0300       ; in RAM (the blitter)
MODE_PF    = 10
GRAV       = 56
JUMPV_LO   = 128
JUMPV_HI   = 251
MAXFALL_HI = 5
INV_FRAMES = 90
MAX_SPR    = 12
GROUND_G   = 32
NROW       = 112
GLIDE      = 96
DROWN_G    = 100
ROOK_SAFE  = 24
NCOURSE    = 6
BLOCK_END  = 19456
FID_MEDAL  = 12
NPF        = 6
ENEMY      = 21504
COIN_GOT   = 21760
COIN_XL    = 128
COIN_XH    = 168
COIN_G     = 208
BS_LO      = 0x4000
BS_HI      = 0x4100
TS_LO      = 0x4200
TS_HI      = 0x4300
LVA        = 0x4400
LVB        = 0x4500
LVC        = 0x4600
SOLID      = 0x4700
OBJ        = 0x4800
FR         = 0x4900
TEXT       = 0x4A00

; main
#addr 0x2000
main:
    ld   STACK_TOP, ac
    ld   ac, [SP]
    ld   LINK_LO, x             ; CALL con_clear
    ld   m_2, [x]
    ld   LINK_HI, x
    ld   m_2 >> 8, [x]
    ld   con_clear >> 8, y
    jmp  con_clear
m_2:
    ld   LINK_LO, x             ; CALL snd_init
    ld   m_3, [x]
    ld   LINK_HI, x
    ld   m_3 >> 8, [x]
    ld   snd_init >> 8, y
    jmp  snd_init
m_3:
    ld   0x5A, y                ; rows 32-479 (x5A40-x5BFF): 4 bpp 4x
    ld   0x40, ac
m_mb1:
    ld   ac, x
    ld   MODE_PF, [y,x]
    inc
    bne  m_mb1
    ld   0x5B, y
    clr  ac
m_mb2:
    ld   ac, x
    ld   MODE_PF, [y,x]
    inc
    bne  m_mb2
    ld   0x20, ac               ; program variables x20-x8F = 0
m_z:
    ld   ac, x
    ld   0, [x]
    add  1, ac
    sub  0x90, ac
    beq  m_z1
    add  0x90, ac
    bra  m_z
m_z1:
    ld   3, ac
    ld   ac, [lives]
    ld   LINK_LO, x             ; CALL load_course
    ld   m_lc, [x]
    ld   LINK_HI, x
    ld   m_lc >> 8, [x]
    ld   load_course >> 8, y
    jmp  load_course
m_lc:
    ld   LINK_LO, x             ; CALL frame_poll
    ld   m_fp, [x]
    ld   LINK_HI, x
    ld   m_fp >> 8, [x]
    ld   frame_poll >> 8, y
    jmp  frame_poll
m_fp:
    ld   [FRAME_LO], ac
    ld   ac, [last_frame]
    ld   frame >> 8, y
    jmp  frame

; frame: wait for vertical blanking, then draw ahead of the beam
frame:
f_wait:
    ld   LINK_LO, x             ; CALL frame_poll
    ld   f_w1, [x]
    ld   LINK_HI, x
    ld   f_w1 >> 8, [x]
    ld   frame_poll >> 8, y
    jmp  frame_poll
f_w1:
    ld   [FRAME_LO], ac
    sub  [last_frame], ac
    bne  f_new
    ld   f_wait >> 8, y
    jmp  f_wait
f_new:
    ld   [FRAME_LO], ac
    ld   ac, [last_frame]
frame_go:
    ld   0x50, y                ; map FF: the strips are in the video RAM
    ld   0xFF, [y,x]            ; (draw_sprites puts MAP_SHADOW back)
    ld   [scl], ac              ; w = (scroll >> 3) & 63
    shr  ac
    shr  ac
    shr  ac
    ld   ac, [tmp]
    ld   [sch], ac
    and  1, ac
    beq  bC_o
    ld   [tmp], ac
    or   0x20, ac
    ld   ac, [tmp]
bC_o:
    ld   [tmp], ac
    and  63, ac
    add  0, ac             ; (this band's strips at BS_LO + 0)
    ld   ac, [bw]
    ld   bC_ret & 0xFF, ac
    ld   ac, [rl]
    ld   bC_ret >> 8, ac
    ld   ac, [rh]
    ld   0x61, ac
    ld   ac, [colpage]
bC_lp:
    ld   [bw], x                ; strip for picture column bw
    ld   BS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   BS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
bC_ret:
    ld   [bw], ac
    add  1, ac
    and  63, ac
    or   0, ac
    ld   ac, [bw]
    ld   [colpage], ac
    add  2, ac
    ld   ac, [colpage]
    sub  1, ac
    bne  bC_lp
band_C_done:
    ld   [scl], ac              ; w = (scroll >> 1) & 63
    shr  ac
    and  63, ac
    add  64, ac             ; (this band's strips at BS_LO + 64)
    ld   ac, [bw]
    ld   bH_ret & 0xFF, ac
    ld   ac, [rl]
    ld   bH_ret >> 8, ac
    ld   ac, [rh]
    ld   0x61, ac
    ld   ac, [colpage]
    ld   hop_1 >> 8, y
    jmp  hop_1                  ; (to the next page)
#addr 0x2100
hop_1:
bH_lp:
    ld   [bw], x                ; strip for picture column bw
    ld   BS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   BS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
bH_ret:
    ld   [bw], ac
    add  1, ac
    and  63, ac
    or   64, ac
    ld   ac, [bw]
    ld   [colpage], ac
    add  2, ac
    ld   ac, [colpage]
    sub  1, ac
    bne  bH_lp
band_H_done:
    ld   [scl], ac              ; course: tile column = (scroll >> 3) & 127,
    and  7, ac                  ; byte in the tile = scroll & 7
    ld   ac, [gj]
    ld   [scl], ac
    shr  ac
    shr  ac
    shr  ac
    ld   ac, [tmp]
    ld   [sch], ac
    and  3, ac
    beq  g_o1
    shl
    shl
    shl
    shl
    shl
    or   [tmp], ac
    ld   ac, [tmp]
g_o1:
    ld   [tmp], ac
    ld   ac, [gt]
    ld   0x61, ac
    ld   ac, [colpage]
g_lp:
    ld   g_r0 & 0xFF, ac      ; tile row 0
    ld   ac, [rl]
    ld   g_r0 >> 8, ac
    ld   ac, [rh]
    ld   [gt], x
    ld   LVA >> 8, y
    ld   [y,x], ac              ; (row, tile) number * 8
    or   [gj], ac
    ld   ac, x
    ld   TS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   TS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
g_r0:
    ld   g_r1 & 0xFF, ac      ; tile row 1
    ld   ac, [rl]
    ld   g_r1 >> 8, ac
    ld   ac, [rh]
    ld   [gt], ac
    add  128, x
    ld   LVA >> 8, y
    ld   [y,x], ac              ; (row, tile) number * 8
    or   [gj], ac
    ld   ac, x
    ld   TS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   TS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
g_r1:
    ld   g_r2 & 0xFF, ac      ; tile row 2
    ld   ac, [rl]
    ld   g_r2 >> 8, ac
    ld   ac, [rh]
    ld   [gt], x
    ld   LVB >> 8, y
    ld   [y,x], ac              ; (row, tile) number * 8
    or   [gj], ac
    ld   ac, x
    ld   TS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   TS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
g_r2:
    ld   g_r3 & 0xFF, ac      ; tile row 3
    ld   ac, [rl]
    ld   g_r3 >> 8, ac
    ld   ac, [rh]
    ld   [gt], ac
    add  128, x
    ld   LVB >> 8, y
    ld   [y,x], ac              ; (row, tile) number * 8
    or   [gj], ac
    ld   ac, x
    ld   TS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   TS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
g_r3:
    ld   g_r4 & 0xFF, ac      ; tile row 4
    ld   ac, [rl]
    ld   g_r4 >> 8, ac
    ld   ac, [rh]
    ld   [gt], x
    ld   LVC >> 8, y
    ld   [y,x], ac              ; (row, tile) number * 8
    or   [gj], ac
    ld   ac, x
    ld   TS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   TS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
g_r4:
    ld   [gj], ac               ; next byte column
    add  1, ac
    and  7, ac
    ld   ac, [gj]
    bne  g_n1
    ld   [gt], ac
    add  1, ac
    and  127, ac
    ld   ac, [gt]
g_n1:
    ld   [colpage], ac
    add  2, ac
    ld   ac, [colpage]
    sub  1, ac
    beq  g_done
    ld   g_lp >> 8, y
    jmp  g_lp
g_done:
drawn_bg:
    ld   hop_2 >> 8, y
    jmp  hop_2                  ; (to the next page)
#addr 0x2200
hop_2:
    ld   LINK_LO, x             ; CALL draw_sprites (RAM)
    ld   f_spr, [x]
    ld   LINK_HI, x
    ld   f_spr >> 8, [x]
    ld   draw_sprites >> 8, y
    jmp  draw_sprites
f_spr:
drawn_all:
    ld   LINK_LO, x             ; CALL snd_update
    ld   f_snd, [x]
    ld   LINK_HI, x
    ld   f_snd >> 8, [x]
    ld   snd_update >> 8, y
    jmp  snd_update
f_snd:
    ld   LINK_LO, x             ; CALL pad_read
    ld   f_pad, [x]
    ld   LINK_HI, x
    ld   f_pad >> 8, [x]
    ld   pad_read >> 8, y
    jmp  pad_read
f_pad:
    ld   LINK_LO, x             ; CALL kbd_scan
    ld   f_kbd, [x]
    ld   LINK_HI, x
    ld   f_kbd >> 8, [x]
    ld   kbd_scan >> 8, y
    jmp  kbd_scan
f_kbd:
    ld   LINK_LO, x             ; CALL menu_poll (Esc: back to the DOS)
    ld   f_mp, [x]
    ld   LINK_HI, x
    ld   f_mp >> 8, [x]
    ld   menu_poll >> 8, y
    jmp  menu_poll
f_mp:
    clr  ac
    ld   ac, [inp]
    ld   [R0], ac               ; pad: Right (bit 7), Left (6), Up (4), B (0)
    and  0x80, ac
    beq  i_1
    ld   1, ac
    ld   ac, [inp]
i_1:
    ld   [R0], ac
    and  0x40, ac
    beq  i_2
    ld   [inp], ac
    or   2, ac
    ld   ac, [inp]
i_2:
    ld   [R0], ac
    and  0x11, ac
    bne  i_3
    ld   [R1], ac               ; A (bit 8)
    and  0x01, ac
    beq  i_4
i_3:
    ld   [inp], ac
    or   4, ac
    ld   ac, [inp]
i_4:
    ld   [KBD_NOW + 7], ac      ; Right key (column 7 row 7, 0 = down)
    and  0x80, ac
    bne  k_1
    ld   [inp], ac
    or   1, ac
    ld   ac, [inp]
k_1:
    ld   [KBD_NOW + 7], ac      ; Left (row 5)
    and  0x20, ac
    bne  k_2
    ld   [inp], ac
    or   2, ac
    ld   ac, [inp]
k_2:
    ld   [KBD_NOW + 6], ac      ; Up (column 6 row 5)
    and  0x20, ac
    beq  k_3
    ld   [KBD_NOW + 7], ac      ; Space (column 7 row 2)
    and  0x04, ac
    bne  k_4
k_3:
    ld   [inp], ac
    or   4, ac
    ld   ac, [inp]
k_4:
    ld   LINK_LO, x             ; CALL game
    ld   f_game, [x]
    ld   LINK_HI, x
    ld   f_game >> 8, [x]
    ld   game >> 8, y
    jmp  game
f_game:
    ld   LINK_LO, x             ; CALL hud
    ld   f_hud, [x]
    ld   LINK_HI, x
    ld   f_hud >> 8, [x]
    ld   hud >> 8, y
    jmp  hud
f_hud:
    ld   frame >> 8, y
    jmp  frame

; load_course: read SKYWARD/Cn.LVL (n = course): 6 sectors to BS_LO on, the rest to x6000 on
load_course:
    ld   [SP], x                ; PUSH_LINK
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   0x50, y                ; map 07 (the library)
    ld   [MAP_SHADOW], ac
    ld   ac, [y,x]
    ld   LINK_LO, x             ; CALL fs_root
    ld   lc_0, [x]
    ld   LINK_HI, x
    ld   lc_0 >> 8, [x]
    ld   fs_root >> 8, y
    jmp  fs_root
lc_0:
    ld   s_dir & 0xFF, ac
    ld   ac, [R0]
    ld   s_dir >> 8, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL fs_open
    ld   lc_1, [x]
    ld   LINK_HI, x
    ld   lc_1 >> 8, [x]
    ld   fs_open >> 8, y
    jmp  fs_open
lc_1:
    ld   [course], ac           ; "Cn.LVL"
    add  0x30, ac
    ld   s_file >> 8, y
    ld   (s_file + 1) & 0xFF, x
    ld   ac, [y,x]
    ld   s_file & 0xFF, ac
    ld   ac, [R0]
    ld   s_file >> 8, ac
    ld   ac, [R1]
    ld   hop_3 >> 8, y
    jmp  hop_3                  ; (to the next page)
#addr 0x2300
hop_3:
    ld   LINK_LO, x             ; CALL fs_open
    ld   lc_2, [x]
    ld   LINK_HI, x
    ld   lc_2 >> 8, [x]
    ld   fs_open >> 8, y
    jmp  fs_open
lc_2:
    beq  lc_3
    ld   0x80, y                ; no file: back to the DOS (dos_back)
    jmp  0x08
lc_3:
    clr  ac
    ld   ac, [R4]
    ld   BS_LO >> 8, ac
    ld   ac, [R5]
lc_rd:
    ld   LINK_LO, x             ; CALL fs_read
    ld   lc_4, [x]
    ld   LINK_HI, x
    ld   lc_4 >> 8, [x]
    ld   fs_read >> 8, y
    jmp  fs_read
lc_4:
    bne  lc_5
    ld   [R5], ac               ; after the tables: the video RAM
    sub  BLOCK_END >> 8, ac
    bne  lc_4a
    ld   0x60, ac
    ld   ac, [R5]
lc_4a:
    ld   lc_rd >> 8, y
    jmp  lc_rd
lc_5:
    ld   LINK_LO, x             ; CALL reset_objs
    ld   lc_6, [x]
    ld   LINK_HI, x
    ld   lc_6 >> 8, [x]
    ld   reset_objs >> 8, y
    jmp  reset_objs
lc_6:
    ld   OBJ >> 8, y            ; the course's header
    ld   0x60, x
    ld   [y,x], ac
    ld   ac, [n_en]
    ld   0x61, x
    ld   [y,x], ac
    ld   ac, [n_med]
    ld   0x62, x
    ld   [y,x], ac
    ld   ac, [goal_lo]
    ld   0x63, x
    ld   [y,x], ac
    ld   ac, [goal_hi]
    ld   0x64, x
    ld   [y,x], ac
    ld   ac, [chk_lo]
    ld   0x67, x
    ld   [y,x], ac
    ld   ac, [chk_hi]
    ld   0x65, x
    ld   [y,x], ac
    ld   ac, [kind]
    ld   0x66, x
    ld   [y,x], ac
    ld   ac, [glider]
    ld   1, ac
    ld   ac, [mode]
    ld   ac, [hud_dirty]
    clr  ac
    ld   ac, [clear_t]
    ld   ac, [facing]
    ld   ac, [sl_n]             ; (the list's routines were the last course's)
    ld   LINK_LO, x             ; CALL respawn
    ld   lc_7, [x]
    ld   LINK_HI, x
    ld   lc_7 >> 8, [x]
    ld   respawn >> 8, y
    jmp  respawn
lc_7:
    clr  ac
    ld   ac, [inv]
    ld   [chk_lo], ac           ; the camera, for the first frame
    sub  30, ac
    ld   ac, [scl]
    ld   [chk_hi], ac
    bcc  lc_8
    sub  1, ac
lc_8:
    and  3, ac
    ld   ac, [sch]
    clr  ac
    ld   ac, [CUR_COL]
    ld   0, ac
    ld   ac, [CUR_ROW]
    ld   0x00, ac
    ld   ac, [R0]
    ld   0x4A, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   lc_t0, [x]
    ld   LINK_HI, x
    ld   lc_t0 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
lc_t0:
    clr  ac
    ld   ac, [CUR_COL]
    ld   2, ac
    ld   ac, [CUR_ROW]
    ld   0x58, ac
    ld   ac, [R0]
    ld   0x4A, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   lc_t1, [x]
    ld   LINK_HI, x
    ld   lc_t1 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
lc_t1:
    clr  ac
    ld   ac, [CUR_COL]
    ld   3, ac
    ld   ac, [CUR_ROW]
    ld   0xB0, ac
    ld   ac, [R0]
    ld   0x4A, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   lc_t2, [x]
    ld   LINK_HI, x
    ld   lc_t2 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
lc_t2:
    clr  ac
    ld   ac, [CUR_COL]
    ld   1, ac
    ld   ac, [CUR_ROW]
    ld   s_score & 0xFF, ac
    ld   ac, [R0]
    ld   s_score >> 8, ac
    ld   ac, [R1]
    ld   hop_4 >> 8, y
    jmp  hop_4                  ; (to the next page)
#addr 0x2400
hop_4:
    ld   LINK_LO, x             ; CALL con_puts
    ld   lc_t9, [x]
    ld   LINK_HI, x
    ld   lc_t9 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
lc_t9:
    ld   LINK_LO, x             ; CALL frame_poll
    ld   lc_fp, [x]
    ld   LINK_HI, x
    ld   lc_fp >> 8, [x]
    ld   frame_poll >> 8, y
    jmp  frame_poll
lc_fp:
    ld   [FRAME_LO], ac
    ld   ac, [last_frame]
    ld   lib_leave >> 8, y
    jmp  lib_leave

; tile_at: AC = 0 when cell ta_g of world byte column ta_hi:ta_lo is not solid
tile_at:
    ld   [ta_g], ac
    sub  GROUND_G, ac
    bcc  ta_0
    clr  ac                     ; above the course: as its top row (the end
ta_0:                           ; walls go all the way up)
    ld   ac, [tmp3]
    sub  80, ac
    bcc  ta_no                  ; below it
    ld   [ta_lo], ac            ; tile column = (x >> 3) & 127
    shr  ac
    shr  ac
    shr  ac
    ld   ac, [dlo]
    ld   [ta_hi], ac
    and  3, ac
    shl
    shl
    shl
    shl
    shl
    or   [dlo], ac
    ld   ac, [dlo]
    ld   [tmp3], ac             ; tile row = (g - 32) / 16: page LVA + row / 2,
    shr  ac                     ; + 128 for an odd row
    shr  ac
    shr  ac
    shr  ac
    ld   ac, [tmp3]
    and  1, ac
    beq  ta_1
    ld   [dlo], ac
    or   0x80, ac
    ld   ac, [dlo]
ta_1:
    ld   [tmp3], ac
    shr  ac
    add  LVA >> 8, ac
    ld   ac, y
    ld   [dlo], x
    ld   [y,x], ac
    ld   ac, x
    ld   SOLID >> 8, y
    ld   [y,x], ac
    ld   [LINK_HI], y
    jmp  [LINK_LO]
ta_no:
    clr  ac
    ld   [LINK_HI], y
    jmp  [LINK_LO]
reset_objs:
    clr  ac                     ; the objects from the course's list (OBJ x00-x67)
    ld   ac, [tmp]
ro_1:
    ld   [tmp], x
    ld   OBJ >> 8, y
    ld   [y,x], ac
    ld   ENEMY >> 8, y
    ld   ac, [y,x]
    ld   [tmp], ac
    add  1, ac
    ld   ac, [tmp]
    sub  0x68, ac
    bne  ro_1
    clr  ac                     ; every medal back
    ld   ac, [tmp]
    ld   COIN_GOT >> 8, y
ro_2:
    ld   [tmp], x
    ld   0, [y,x]
    ld   [tmp], ac
    add  1, ac
    ld   ac, [tmp]
    sub  40, ac
    bne  ro_2
    ld   [LINK_HI], y
    jmp  [LINK_LO]
respawn:
    ld   [chk_lo], ac           ; at the last place stood on, from the top
    ld   ac, [pxl]
    ld   [chk_hi], ac
    ld   ac, [pxh]
    clr  ac
    ld   ac, [pyh]
    ld   ac, [pyl]
    ld   ac, [vyl]
    ld   ac, [vyh]
    ld   ac, [onground]
    ld   INV_FRAMES, ac
    ld   ac, [inv]
    ld   [LINK_HI], y
    jmp  [LINK_LO]

; game: the mode, then movement, objects, sprite list
game:
    ld   [SP], x                ; PUSH_LINK
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   hop_5 >> 8, y
    jmp  hop_5                  ; (to the next page)
#addr 0x2500
hop_5:
    ld   [inp], ac
    and  4, ac
    ld   ac, [jnow]
    ld   [mode], ac
    bne  gm_m1
    ld   gm_play >> 8, y
    jmp  gm_play
gm_m1:
    sub  1, ac
    bne  gm_clr
    ld   [jnow], ac             ; waiting: the jump key, newly down?
    beq  gm_still
    ld   [jprev], ac
    bne  gm_still
    ld   [kind], ac             ; a picture: the next course
    beq  gm_go
    ld   next_course >> 8, y
    jmp  next_course
gm_go:
    clr  ac                     ; a course: play
    ld   ac, [mode]
    ld   76, ac
    ld   LINK_LO, x             ; CALL snd_beep
    ld   gm_gb, [x]
    ld   LINK_HI, x
    ld   gm_gb >> 8, [x]
    ld   snd_beep >> 8, y
    jmp  snd_beep
gm_gb:
gm_still:
    clr  ac
    ld   ac, [inp]
    ld   gm_play >> 8, y
    jmp  gm_play
gm_clr:
    ld   [clear_t], ac          ; course clear: count down, then the next one
    sub  1, ac
    ld   ac, [clear_t]
    bne  gm_still
    ld   next_course >> 8, y
    jmp  next_course

; next_course: course + 1 (after the ending: a new game), load it; leaves game
next_course:
    ld   [course], ac
    add  1, ac
    sub  NCOURSE, ac
    bcs  nc_1
    clr  ac                     ; a new game
    ld   ac, [score_lo]
    ld   ac, [score_hi]
    ld   ac, [coins]
    ld   3, ac
    ld   ac, [lives]
    ld   0 - NCOURSE, ac
nc_1:
    add  NCOURSE, ac
    ld   ac, [course]
    ld   4, ac                  ; (the key that got here is still down)
    ld   ac, [jprev]
    ld   LINK_LO, x             ; CALL load_course
    ld   nc_2, [x]
    ld   LINK_HI, x
    ld   nc_2 >> 8, [x]
    ld   load_course >> 8, y
    jmp  load_course
nc_2:
    ld   lib_leave >> 8, y
    jmp  lib_leave

; game: the player, sideways
gm_play:
    ld   hop_6 >> 8, y
    jmp  hop_6                  ; (to the next page)
#addr 0x2600
hop_6:
    clr  ac
    ld   ac, [moved]
    ld   [inp], ac              ; right
    and  1, ac
    beq  gm_nr
    clr  ac
    ld   ac, [facing]
    ld   [pxl], ac              ; wall at byte 8, rows 1, 8, 15?
    add  8, ac
    ld   ac, [ta_lo]
    ld   [pxh], ac
    bcc  gm_r1
    add  1, ac
gm_r1:
    ld   ac, [ta_hi]
    ld   1, ac
    ld   ac, [moved]
    bra  gm_side
gm_nr:
    ld   [inp], ac              ; left
    and  2, ac
    bne  gm_l0
    ld   gm_vert >> 8, y
    jmp  gm_vert
gm_l0:
    ld   NPF, ac
    ld   ac, [facing]
    ld   [pxl], ac              ; wall at byte -1?
    sub  1, ac
    ld   ac, [ta_lo]
    ld   [pxh], ac
    bcc  gm_l1
    sub  1, ac
gm_l1:
    ld   ac, [ta_hi]
    ld   2, ac
    ld   ac, [moved]
gm_side:
    ld   [pyh], ac
    add  1, ac
    ld   ac, [ta_g]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_s1, [x]
    ld   LINK_HI, x
    ld   gm_s1 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_s1:
    bne  gm_block
    ld   [pyh], ac
    add  8, ac
    ld   ac, [ta_g]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_s2, [x]
    ld   LINK_HI, x
    ld   gm_s2 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_s2:
    bne  gm_block
    ld   [pyh], ac
    add  15, ac
    ld   ac, [ta_g]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_s3, [x]
    ld   LINK_HI, x
    ld   gm_s3 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_s3:
    bne  gm_block
    ld   [moved], ac            ; free: move one byte column
    sub  1, ac
    bne  gm_ml
    ld   [pxl], ac
    add  1, ac
    ld   ac, [pxl]
    bne  gm_vert_j
    ld   [pxh], ac
    add  1, ac
    and  3, ac
    ld   ac, [pxh]
    bra  gm_vert_j
gm_ml:
    ld   [pxl], ac
    sub  1, ac
    ld   ac, [pxl]
    xor  0xFF, ac
    bne  gm_vert_j
    ld   [pxh], ac
    sub  1, ac
    and  3, ac
    ld   ac, [pxh]
    bra  gm_vert_j
gm_block:
    clr  ac
    ld   ac, [moved]
gm_vert_j:
    ld   gm_vert >> 8, y
    jmp  gm_vert

; game: jumping, gliding and falling
gm_vert:
    ld   hop_7 >> 8, y
    jmp  hop_7                  ; (to the next page)
#addr 0x2700
hop_7:
    clr  ac
    ld   ac, [gliding]
    ld   [jnow], ac             ; jump from the ground, on a new key press
    beq  gm_g0
    ld   [jprev], ac
    bne  gm_g0
    ld   [onground], ac
    beq  gm_g0
    ld   JUMPV_LO, ac
    ld   ac, [vyl]
    ld   JUMPV_HI, ac
    ld   ac, [vyh]
    ld   72, ac
    ld   LINK_LO, x             ; CALL snd_beep
    ld   gm_js, [x]
    ld   LINK_HI, x
    ld   gm_js >> 8, [x]
    ld   snd_beep >> 8, y
    jmp  snd_beep
gm_js:
gm_g0:
    ld   [vyl], ac              ; gravity
    add  GRAV, ac
    ld   ac, [vyl]
    ld   [vyh], ac
    bcc  gm_g1
    add  1, ac
gm_g1:
    ld   ac, [vyh]
    blt  gm_g2                  ; going up
    ld   [glider], ac           ; falling with the glider and the key held:
    beq  gm_ng                  ; no faster than GLIDE
    ld   [jnow], ac
    beq  gm_ng
    ld   [onground], ac
    bne  gm_ng
    ld   1, ac
    ld   ac, [gliding]
    ld   [vyh], ac
    bne  gm_gl
    ld   [vyl], ac
    sub  GLIDE, ac
    bcs  gm_ng
gm_gl:
    clr  ac
    ld   ac, [vyh]
    ld   GLIDE, ac
    ld   ac, [vyl]
gm_ng:
    ld   [vyh], ac
    sub  MAXFALL_HI, ac
    bcs  gm_g2
    ld   MAXFALL_HI, ac
    ld   ac, [vyh]
    clr  ac
    ld   ac, [vyl]
gm_g2:
    ld   [pyl], ac              ; y += vy
    add  [vyl], ac
    ld   ac, [pyl]
    ld   [vyh], ac
    blt  gm_up
    ld   [pyh], ac
    bcc  gm_g3
    add  1, ac
gm_g3:
    add  [vyh], ac
    ld   ac, [pyh]
    ld   gm_fall >> 8, y
    jmp  gm_fall
gm_up:
    ld   [pyh], ac              ; (vy < 0: the high bytes and the carry)
    bcc  gm_g4
    add  1, ac
gm_g4:
    add  [vyh], ac
    ld   ac, [pyh]
    blt  gm_top                 ; above the screen: stop there
    ld   gm_head >> 8, y
    jmp  gm_head
gm_top:
    clr  ac
    ld   ac, [pyh]
    ld   ac, [pyl]
    ld   ac, [vyl]
    ld   ac, [vyh]
    ld   gm_obj >> 8, y
    jmp  gm_obj
gm_head:
    ld   [pyh], ac              ; head in a solid tile?
    ld   ac, [ta_g]
    ld   [pxl], ac
    add  1, ac
    ld   ac, [ta_lo]
    ld   [pxh], ac
    bcc  gm_h1
    add  1, ac
gm_h1:
    ld   ac, [ta_hi]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_h2, [x]
    ld   LINK_HI, x
    ld   gm_h2 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_h2:
    bne  gm_bump
    ld   [ta_lo], ac
    add  5, ac
    ld   ac, [ta_lo]
    bcc  gm_h3c
    ld   [ta_hi], ac
    add  1, ac
    ld   ac, [ta_hi]
gm_h3c:
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_h3, [x]
    ld   LINK_HI, x
    ld   gm_h3 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_h3:
    beq  gm_h4
gm_bump:
    ld   [pyh], ac              ; below that tile
    sub  GROUND_G, ac
    and  0xF0, ac
    add  GROUND_G + 16, ac
    ld   ac, [pyh]
    clr  ac
    ld   ac, [pyl]
    ld   ac, [vyl]
    ld   ac, [vyh]
gm_h4:
    clr  ac
    ld   ac, [onground]
    ld   gm_obj >> 8, y
    jmp  gm_obj
    ld   hop_8 >> 8, y
    jmp  hop_8                  ; (to the next page)
#addr 0x2800
hop_8:
gm_fall:
    ld   [pyh], ac              ; out of the course: a life
    sub  DROWN_G, ac
    bcs  gm_f0
    ld   LINK_LO, x
    ld   gm_obj & 0xFF, [x]
    ld   LINK_HI, x
    ld   gm_obj >> 8, [x]
    ld   lose_life >> 8, y
    jmp  lose_life
gm_f0:
    ld   [pyh], ac              ; feet on a solid tile?
    add  16, ac
    ld   ac, [ta_g]
    ld   [pxl], ac
    add  1, ac
    ld   ac, [ta_lo]
    ld   [pxh], ac
    bcc  gm_f1
    add  1, ac
gm_f1:
    ld   ac, [ta_hi]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_f2, [x]
    ld   LINK_HI, x
    ld   gm_f2 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_f2:
    bne  gm_land
    ld   [ta_lo], ac
    add  5, ac
    ld   ac, [ta_lo]
    bcc  gm_f3c
    ld   [ta_hi], ac
    add  1, ac
    ld   ac, [ta_hi]
gm_f3c:
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_f3, [x]
    ld   LINK_HI, x
    ld   gm_f3 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_f3:
    bne  gm_land
    clr  ac
    ld   ac, [onground]
    ld   gm_obj >> 8, y
    jmp  gm_obj
gm_land:
    ld   [pyh], ac              ; stand on the tile: y = its top - 16
    add  16 - GROUND_G, ac
    and  0xF0, ac
    add  GROUND_G - 16, ac
    ld   ac, [pyh]
    clr  ac
    ld   ac, [pyl]
    ld   ac, [vyl]
    ld   ac, [vyh]
    ld   1, ac
    ld   ac, [onground]
    ld   [pxl], ac              ; checkpoint
    ld   ac, [chk_lo]
    ld   [pxh], ac
    ld   ac, [chk_hi]
    ld   gm_obj >> 8, y
    jmp  gm_obj

; lose_life: a life (none left: the title again), noise, respawn; returns via LINK
lose_life:
    ld   [LINK_LO], ac          ; keep the return address over snd_noise
    ld   ac, [ll_lo]
    ld   [LINK_HI], ac
    ld   ac, [ll_hi]
    ld   1, ac
    ld   ac, [hud_dirty]
    ld   8, ac                  ; noise: rumble, 30 frames, fading
    ld   ac, [R0]
    ld   30, ac
    ld   ac, [R2]
    ld   3, ac
    ld   ac, [R3]
    ld   90, ac
    ld   LINK_LO, x             ; CALL snd_noise
    ld   ll_2, [x]
    ld   LINK_HI, x
    ld   ll_2 >> 8, [x]
    ld   snd_noise >> 8, y
    jmp  snd_noise
ll_2:
    ld   [lives], ac
    sub  1, ac
    ld   ac, [lives]
    bne  ll_1
    ld   NCOURSE - 1, ac        ; game over: the title, a new game
    ld   ac, [course]
    ld   next_course >> 8, y
    jmp  next_course
ll_1:
    ld   [ll_lo], ac
    ld   ac, [LINK_LO]
    ld   [ll_hi], ac
    ld   ac, [LINK_HI]
    ld   respawn >> 8, y
    jmp  respawn
sl_add:
    ld   [sl_n], ac
    sub  MAX_SPR, ac
    beq  sa_full
    ld   [sl_n], ac
    add  SL_C, x
    ld   [dlo], ac
    ld   ac, [x]
    ld   [sl_n], ac
    add  SL_G, x
    ld   [tmp3], ac
    ld   ac, [x]
    ld   [tmp], x
    ld   FR >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp2]
    ld   [sl_n], ac
    add  SL_LO, x
    ld   [tmp2], ac
    ld   ac, [x]
    ld   [tmp], ac
    add  128, x
    ld   FR >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp2]
    ld   [sl_n], ac
    add  SL_HI, x
    ld   [tmp2], ac
    ld   ac, [x]
    ld   [sl_n], ac
    add  1, ac
    ld   ac, [sl_n]
sa_full:
    ld   [LINK_HI], y
    jmp  [LINK_LO]

; game: camera, the goal, medals
gm_obj:
    ld   hop_9 >> 8, y
    jmp  hop_9                  ; (to the next page)
#addr 0x2900
hop_9:
    ld   [onground], ac         ; animation: count while running on the ground
    beq  go_a1
    ld   [moved], ac
    beq  go_a1
    ld   [anim], ac
    add  1, ac
    ld   ac, [anim]
go_a1:
    ld   [inv], ac
    beq  go_a2
    sub  1, ac
    ld   ac, [inv]
go_a2:
    ld   [pxl], ac              ; camera: scroll = px - 30 (the player at
    sub  30, ac                 ; that screen byte column)
    ld   ac, [scl]
    ld   [pxh], ac
    bcc  go_a3
    sub  1, ac
go_a3:
    and  3, ac
    ld   ac, [sch]
    clr  ac
    ld   ac, [sl_n]
    ld   ac, [o_i]
    ld   [mode], ac             ; playing, and at the goal: course clear
    bne  go_ng
    ld   [pxh], ac
    sub  [goal_hi], ac
    bcs  go_ng
    bne  go_goal
    ld   [pxl], ac
    sub  [goal_lo], ac
    bcs  go_ng
    bra  go_goal
go_ng:
    ld   go_c >> 8, y
    jmp  go_c
go_goal:
    ld   2, ac
    ld   ac, [mode]
    ld   90, ac
    ld   ac, [clear_t]
    ld   LINK_LO, x
    ld   go_c & 0xFF, [x]
    ld   LINK_HI, x
    ld   go_c >> 8, [x]
    ld   84, ac
    ld   snd_beep >> 8, y
    jmp  snd_beep
go_c:
    ld   [o_i], ac              ; medal o_i (none left: the objects)
    sub  [n_med], ac
    bne  go_c00
    ld   go_cd >> 8, y
    jmp  go_cd
go_c00:
    ld   [o_i], x               ; taken?
    ld   COIN_GOT >> 8, y
    ld   [y,x], ac
    beq  go_c0
    ld   go_cn >> 8, y
    jmp  go_cn
go_c0:
    ld   OBJ >> 8, y
    ld   [o_i], ac
    add  COIN_XH, x
    ld   [y,x], ac
    ld   ac, [dhi]
    ld   [o_i], ac
    add  COIN_XL, x
    ld   [y,x], ac
    sub  [scl], ac
    ld   ac, [dlo]
    ld   [dhi], ac
    bcc  go_cn_sc_1
    sub  1, ac
go_cn_sc_1:
    sub  [sch], ac
    ld   ac, [dhi]
    ld   [dlo], ac
    add  8, ac
    ld   ac, [dlo]
    ld   [dhi], ac
    bcc  go_cn_sc_2
    add  1, ac
go_cn_sc_2:
    and  3, ac
    bne  go_cn_sc_off
    ld   [dlo], ac
    sub  88, ac
    bcs  go_cn_sc_on
go_cn_sc_off:
    ld   go_cn >> 8, y
    jmp  go_cn
go_cn_sc_on:
    ld   OBJ >> 8, y            ; top cell + 32
    ld   [o_i], ac
    add  COIN_G, x
    ld   [y,x], ac
    add  32, ac
    ld   ac, [tmp3]
    ld   [dlo], ac              ; touching the player?  cx - px = dlo - 38,
    sub  35, ac                 ; in -3..6
    sub  10, ac
    bcc  go_cadd
    ld   [tmp3], ac             ; cg - pyh in -7..15: (cg + 32) - pyh - 25
    sub  [pyh], ac
    sub  25, ac
    sub  23, ac
    bcc  go_cadd
    ld   [o_i], x               ; taken: +10, a beep
    ld   COIN_GOT >> 8, y
    ld   1, [y,x]
    ld   [coins], ac
    add  1, ac
    ld   ac, [coins]
    ld   [score_lo], ac
    add  10, ac
    ld   ac, [score_lo]
    bcc  go_cs
    ld   [score_hi], ac
    add  1, ac
    ld   ac, [score_hi]
go_cs:
    ld   1, ac
    ld   ac, [hud_dirty]
    ld   LINK_LO, x
    ld   go_cn & 0xFF, [x]
    ld   LINK_HI, x
    ld   go_cn >> 8, [x]
    ld   88, ac
    ld   snd_beep >> 8, y
    jmp  snd_beep
go_cadd:
    ld   [FRAME_LO], ac         ; frame: medal 1-4, a step every 8 frames
    shr  ac
    shr  ac
    shr  ac
    and  3, ac
    add  FID_MEDAL, ac
    ld   ac, [tmp]
    ld   hop_10 >> 8, y
    jmp  hop_10                  ; (to the next page)
#addr 0x2A00
hop_10:
    ld   LINK_LO, x             ; CALL sl_add
    ld   go_ca1, [x]
    ld   LINK_HI, x
    ld   go_ca1 >> 8, [x]
    ld   sl_add >> 8, y
    jmp  sl_add
go_ca1:
go_cn:
    ld   [o_i], ac
    add  1, ac
    ld   ac, [o_i]
    ld   go_c >> 8, y
    jmp  go_c
go_cd:
    clr  ac
    ld   ac, [o_i]
    ld   go_e >> 8, y
    jmp  go_e

; game: the objects (Bumblers, Buzzbees, Baron Rook, pictures)
go_e:
    ld   [o_i], ac
    sub  [n_en], ac
    bne  go_e00
    ld   go_pl >> 8, y
    jmp  go_pl
go_e00:
    ld   ENEMY >> 8, y          ; alive?
    ld   [o_i], ac
    add  0x40, x
    ld   [y,x], ac
    bne  go_e1
    ld   go_en >> 8, y
    jmp  go_en
go_e1:
    ld   [o_i], ac
    add  0x48, x
    ld   [y,x], ac
    ld   ac, [ekind]
    and  2, ac                  ; a picture stays where it is
    bne  go_e5
    ld   [FRAME_LO], ac         ; move a byte every other frame
    and  1, ac
    beq  go_e5
    ld   [o_i], ac
    add  0x18, x
    ld   [y,x], ac              ; direction 0 right, 1 left
    bne  go_el
    ld   [o_i], x               ; right: x + 1
    ld   [y,x], ac
    add  1, ac
    ld   ac, [y,x]
    bne  go_e2
    ld   [o_i], ac
    add  8, x
    ld   [y,x], ac
    add  1, ac
    and  3, ac
    ld   ac, [y,x]
go_e2:
    ld   [o_i], ac              ; at the right end: turn
    add  0x30, x
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   [o_i], x
    ld   [y,x], ac
    sub  [tmp], ac
    bne  go_e5
    ld   [o_i], ac
    add  0x18, x
    ld   1, [y,x]
    bra  go_e5
go_el:
    ld   [o_i], x               ; left: x - 1
    ld   [y,x], ac
    sub  1, ac
    ld   ac, [y,x]
    xor  0xFF, ac
    bne  go_e3
    ld   [o_i], ac
    add  8, x
    ld   [y,x], ac
    sub  1, ac
    and  3, ac
    ld   ac, [y,x]
go_e3:
    ld   [o_i], ac              ; at the left end: turn
    add  0x20, x
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   [o_i], x
    ld   [y,x], ac
    sub  [tmp], ac
    bne  go_e5
    ld   [o_i], ac
    add  0x18, x
    ld   0, [y,x]
go_e5:
    ld   hop_11 >> 8, y
    jmp  hop_11                  ; (to the next page)
#addr 0x2B00
hop_11:
    ld   ENEMY >> 8, y
    ld   [o_i], ac
    add  8, x
    ld   [y,x], ac
    ld   ac, [dhi]
    ld   [o_i], ac
    add  0, x
    ld   [y,x], ac
    sub  [scl], ac
    ld   ac, [dlo]
    ld   [dhi], ac
    bcc  go_en_sc_1
    sub  1, ac
go_en_sc_1:
    sub  [sch], ac
    ld   ac, [dhi]
    ld   [dlo], ac
    add  8, ac
    ld   ac, [dlo]
    ld   [dhi], ac
    bcc  go_en_sc_2
    add  1, ac
go_en_sc_2:
    and  3, ac
    bne  go_en_sc_off
    ld   [dlo], ac
    sub  88, ac
    bcs  go_en_sc_on
go_en_sc_off:
    ld   go_en >> 8, y
    jmp  go_en
go_en_sc_on:
    ld   ENEMY >> 8, y          ; top cell + 32
    ld   [o_i], ac
    add  0x10, x
    ld   [y,x], ac
    add  32, ac
    ld   ac, [tmp3]
    sub  [pyh], ac              ; eg - pyh, in tmp2
    sub  32, ac
    ld   ac, [tmp2]
    ld   [mode], ac             ; only while playing, not just after a lost
    bne  go_eaj                ; life, and not a picture
    ld   [inv], ac
    bne  go_eaj
    ld   [ekind], ac
    and  2, ac
    bne  go_eaj
    ld   [ekind], ac
    bne  go_ebig
    ld   [dlo], ac              ; touching the player?  ex - px in -6..6
    sub  32, ac
    sub  13, ac
    bcc  go_eaj
    ld   [tmp2], ac             ; eg - pyh in -14..14
    add  14, ac
    sub  29, ac
    bcc  go_eaj
    ld   go_hit >> 8, y
    jmp  go_hit
go_ebig:
    ld   [dlo], ac              ; Rook, 32 x 32: ex - px in -14..5
    sub  24, ac
    sub  20, ac
    bcc  go_eaj
    ld   [tmp2], ac             ; eg - pyh in -30..14
    add  30, ac
    sub  45, ac
    bcc  go_eaj
    ld   go_hit >> 8, y
    jmp  go_hit
go_eaj:
    ld   go_eadd >> 8, y
    jmp  go_eadd
    ld   hop_12 >> 8, y
    jmp  hop_12                  ; (to the next page)
#addr 0x2C00
hop_12:
go_eadd:
    ld   ENEMY >> 8, y          ; frame: the object's first, + 1 every 16 frames
    ld   [o_i], ac
    add  0x50, x
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   [FRAME_LO], ac
    shr  ac
    shr  ac
    shr  ac
    shr  ac
    and  1, ac
    ld   ac, [tmp2]
    ld   [ekind], ac
    and  1, ac
    bne  go_e4p
    ld   [tmp], ac
    add  [tmp2], ac
    ld   ac, [tmp]
    ld   LINK_LO, x             ; CALL sl_add
    ld   go_ea1, [x]
    ld   LINK_HI, x
    ld   go_ea1 >> 8, [x]
    ld   sl_add >> 8, y
    jmp  sl_add
go_ea1:
    ld   go_en >> 8, y
    jmp  go_en
go_e4p:
    ld   [tmp2], ac             ; 32 x 32: four pieces, + 4 for the other frame
    shl
    shl
    add  [tmp], ac
    ld   ac, [tmp]
    ld   LINK_LO, x             ; CALL sl_add
    ld   go_eb1, [x]
    ld   LINK_HI, x
    ld   go_eb1 >> 8, [x]
    ld   sl_add >> 8, y
    jmp  sl_add
go_eb1:
    ld   [tmp], ac
    add  1, ac
    ld   ac, [tmp]
    ld   [dlo], ac
    add  8, ac
    ld   ac, [dlo]
    ld   LINK_LO, x             ; CALL sl_add
    ld   go_eb2, [x]
    ld   LINK_HI, x
    ld   go_eb2 >> 8, [x]
    ld   sl_add >> 8, y
    jmp  sl_add
go_eb2:
    ld   [tmp], ac
    add  1, ac
    ld   ac, [tmp]
    ld   [dlo], ac
    sub  8, ac
    ld   ac, [dlo]
    ld   [tmp3], ac
    add  16, ac
    ld   ac, [tmp3]
    ld   LINK_LO, x             ; CALL sl_add
    ld   go_eb3, [x]
    ld   LINK_HI, x
    ld   go_eb3 >> 8, [x]
    ld   sl_add >> 8, y
    jmp  sl_add
go_eb3:
    ld   [tmp], ac
    add  1, ac
    ld   ac, [tmp]
    ld   [dlo], ac
    add  8, ac
    ld   ac, [dlo]
    ld   LINK_LO, x             ; CALL sl_add
    ld   go_eb4, [x]
    ld   LINK_HI, x
    ld   go_eb4 >> 8, [x]
    ld   sl_add >> 8, y
    jmp  sl_add
go_eb4:
    ld   go_en >> 8, y
    jmp  go_en
go_en:
    ld   [o_i], ac
    add  1, ac
    ld   ac, [o_i]
    ld   go_e >> 8, y
    jmp  go_e

; game: an object touches the player; the player into the list
    ld   hop_13 >> 8, y
    jmp  hop_13                  ; (to the next page)
#addr 0x2D00
hop_13:
go_hit:
    ld   [vyh], ac              ; falling and feet in its top half: landed on it
    blt  go_hurt
    ld   [tmp2], ac             ; eg - pyh >= 8
    sub  8, ac
    blt  go_hurt
    ld   0xFD, ac               ; bounce up
    ld   ac, [vyh]
    clr  ac
    ld   ac, [vyl]
    ld   1, ac
    ld   ac, [hud_dirty]
    ld   ENEMY >> 8, y
    ld   [ekind], ac
    beq  go_dead
    ld   [o_i], ac              ; Rook: three times
    add  0x58, x
    ld   [y,x], ac
    sub  1, ac
    ld   ac, [y,x]
    beq  go_rook
    ld   ROOK_SAFE, ac          ; (safe while bouncing off him)
    ld   ac, [inv]
    ld   LINK_LO, x
    ld   go_eadd & 0xFF, [x]
    ld   LINK_HI, x
    ld   go_eadd >> 8, [x]
    ld   48, ac
    ld   snd_beep >> 8, y
    jmp  snd_beep
go_rook:
    ld   2, ac                  ; beaten: + 1000, the course is clear
    ld   ac, [mode]
    ld   150, ac
    ld   ac, [clear_t]
    ld   [score_lo], ac
    add  132, ac                ; (1000 - 100 = x384)
    ld   ac, [score_lo]
    ld   [score_hi], ac
    bcc  go_rk1
    add  1, ac
go_rk1:
    add  3, ac
    ld   ac, [score_hi]
    ld   ENEMY >> 8, y
go_dead:
    ld   [o_i], ac
    add  0x40, x
    ld   0, [y,x]
    ld   [score_lo], ac         ; +100
    add  100, ac
    ld   ac, [score_lo]
    bcc  go_h1
    ld   [score_hi], ac
    add  1, ac
    ld   ac, [score_hi]
go_h1:
    ld   LINK_LO, x
    ld   go_en & 0xFF, [x]
    ld   LINK_HI, x
    ld   go_en >> 8, [x]
    ld   60, ac
    ld   snd_beep >> 8, y
    jmp  snd_beep
go_hurt:
    ld   LINK_LO, x
    ld   go_eadd & 0xFF, [x]
    ld   LINK_HI, x
    ld   go_eadd >> 8, [x]
    ld   lose_life >> 8, y
    jmp  lose_life
go_pl:
    ld   [inv], ac              ; the player last (blinks while safe)
    and  4, ac
    bne  go_done
    ld   38, ac                 ; the screen byte column + 8
    ld   ac, [dlo]
    ld   [pyh], ac
    add  32, ac
    ld   ac, [tmp3]
    ld   [onground], ac         ; frame: glide, jump, run 1-3, stand
    bne  go_p1
    ld   4, ac
    ld   ac, [tmp]
    ld   [gliding], ac
    beq  go_p2
    ld   5, ac
    bra  go_p3
go_p2:
    ld   [tmp], ac
    bra  go_p3
go_p1:
    ld   [moved], ac
    beq  go_p3
    ld   [anim], ac             ; run: 1, 2, 3, 2 a step every 4 frames
    shr  ac
    shr  ac
    and  3, ac
    add  RUNSEQ & 0xFF, x
    ld   RUNSEQ >> 8, y
    ld   [y,x], ac
go_p3:
    add  [facing], ac
    ld   ac, [tmp]
    ld   LINK_LO, x             ; CALL sl_add
    ld   go_p4, [x]
    ld   LINK_HI, x
    ld   go_p4 >> 8, [x]
    ld   sl_add >> 8, y
    jmp  sl_add
go_p4:
go_done:
    ld   [jnow], ac
    ld   ac, [jprev]
    ld   lib_leave >> 8, y
    jmp  lib_leave

; hud: the score line when it changed
hud:
    ld   [SP], x                ; PUSH_LINK
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [hud_dirty], ac
    bne  hu_s
    ld   lib_leave >> 8, y
    jmp  lib_leave
hu_s:
    clr  ac
    ld   ac, [hud_dirty]
    ld   6, ac                  ; score at column 6
    ld   ac, [CUR_COL]
    ld   1, ac
    ld   ac, [CUR_ROW]
    ld   [score_lo], ac
    ld   ac, [R0]
    ld   [score_hi], ac
    ld   ac, [R1]
    ld   hop_14 >> 8, y
    jmp  hop_14                  ; (to the next page)
#addr 0x2E00
hop_14:
    ld   LINK_LO, x             ; CALL con_dec16
    ld   hu_1, [x]
    ld   LINK_HI, x
    ld   hu_1 >> 8, [x]
    ld   con_dec16 >> 8, y
    jmp  con_dec16
hu_1:
    ld   s_sp >> 8, ac
    ld   ac, [R1]
    ld   s_sp & 0xFF, ac
    ld   ac, [R0]
    ld   LINK_LO, x             ; CALL con_puts
    ld   hu_2, [x]
    ld   LINK_HI, x
    ld   hu_2 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
hu_2:
    ld   22, ac                 ; medals at column 22
    ld   ac, [CUR_COL]
    ld   [coins], ac
    ld   LINK_LO, x             ; CALL con_dec8
    ld   hu_3, [x]
    ld   LINK_HI, x
    ld   hu_3 >> 8, [x]
    ld   con_dec8 >> 8, y
    jmp  con_dec8
hu_3:
    ld   s_sp >> 8, ac
    ld   ac, [R1]
    ld   s_sp & 0xFF, ac
    ld   ac, [R0]
    ld   LINK_LO, x             ; CALL con_puts
    ld   hu_4, [x]
    ld   LINK_HI, x
    ld   hu_4 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
hu_4:
    ld   37, ac                 ; lives at column 37
    ld   ac, [CUR_COL]
    ld   [lives], ac
    ld   LINK_LO, x             ; CALL con_dec8
    ld   hu_5, [x]
    ld   LINK_HI, x
    ld   hu_5 >> 8, [x]
    ld   con_dec8 >> 8, y
    jmp  con_dec8
hu_5:
    ld   lib_leave >> 8, y
    jmp  lib_leave

; text and tables
#addr 0x2F00
s_score: #d "SCORE 0        MEDALS 0        TOBI  3", 0x00
s_sp:    #d "  ", 0x00
s_dir:   #d "SKYWARD", 0x00
s_file:  #d "C0.LVL", 0x00
RUNSEQ:  #d8 1, 2, 3, 2
